#include <fstream>
#include <iostream>
std::vector<uint8_t> read(const char*p){std::ifstream f(p,std::ios::binary);if(!f)throw std::runtime_error("fixture missing");return {(std::istreambuf_iterator<char>(f)),{}};}
int main(int argc,char**argv){try{
 static_assert(sizeof(void*)==8,"x64 required");if(argc!=4)throw std::runtime_error("synthetic VTX installed VTX reference required");auto synthetic=read(argv[1]);auto mapped=readSfmVtxGeometryCandidate(synthetic,123);if(mapped.size()!=1||mapped[0].triangles!=std::vector<std::array<uint32_t,3>>{{9,7,2}})throw std::runtime_error("synthetic mapping");unsigned rejected=0;for(size_t n=0;n<synthetic.size();++n){bool failed=false;try{readSfmVtxGeometryCandidate({synthetic.begin(),synthetic.begin()+n},123);}catch(const std::runtime_error&){failed=true;}if(!failed)throw std::runtime_error("accepted truncation");++rejected;}
 for(auto edit:std::vector<std::pair<size_t,uint32_t>>{{0,8},{16,124},{20,9},{28,0xffffffff},{32,175},{44,2},{73,4},{77,0xffffff9c},{106,4},{110,0xffffffff},{114,4},{125,0xffffffff},{133,1}}){auto changed=synthetic;std::memcpy(changed.data()+edit.first,&edit.second,4);bool failed=false;try{readSfmVtxGeometryCandidate(changed,123);}catch(const std::runtime_error&){failed=true;}if(!failed)throw std::runtime_error("accepted mutation");++rejected;}
 auto real=read(argv[2]);auto meshes=readSfmVtxGeometryCandidate(real,3484591680u);std::vector<uint8_t>output;auto append=[&](uint32_t v){auto p=reinterpret_cast<const uint8_t*>(&v);output.insert(output.end(),p,p+4);};size_t triangles=0;for(auto&m:meshes){append(m.body);append(m.model);append(m.lod);append(m.mesh);append(uint32_t(m.triangles.size()));for(auto&t:m.triangles)for(auto v:t)append(v);triangles+=m.triangles.size();}if(output!=read(argv[3])||meshes.size()!=21||triangles!=66146)throw std::runtime_error("Python topology differential");std::cout<<"x64 VTX exact Python differential meshes="<<meshes.size()<<" triangles="<<triangles<<" malformed_rejections="<<rejected<<'\n';return 0;
 }catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
